function o(t,e={day:"2-digit",month:"short",year:"numeric"}){return t?new Date(t).toLocaleDateString("es-MX",e):"—"}function i(t){if(!t)return"";const e=new Date(t),n=e.getFullYear(),a=String(e.getMonth()+1).padStart(2,"0"),r=String(e.getDate()).padStart(2,"0");return`${n}-${a}-${r}`}const u=t=>{if(!t)return"";const e=new Date(t),n=e.getTimezoneOffset()*6e4;return new Date(e.getTime()-n).toISOString().slice(0,16)};function c(t,e={day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:!1}){return t?new Date(t).toLocaleString("es-MX",e):"—"}function f(t){if(!t)return 0;const e=new Date(t).getTime()-Date.now();return Math.max(0,Math.ceil(e/(1e3*60*60*24)))}function s(t,e){if(!t||!e)return 0;const n=new Date(t).getTime(),a=new Date(e).getTime(),r=Date.now();return r<=n?0:r>=a?100:Math.round((r-n)/(a-n)*100)}function m(t,e){return new Intl.NumberFormat("es-MX",{style:"currency",currency:"MXN",...e}).format(t)}function d(t){return t.toLocaleString("en-US")}export{m as a,c as b,i as c,f as d,d as e,o as f,s as p,u as t};
